<?php
require __DIR__.'/includes/init.php';
if(!empty($_SESSION['uid'])) redirect($_SESSION['role']==='admin'?'admin/index.php':'dashboard.php');
$err='';
if(is_post()){
  csrf_check();
  $r=attempt_login(strtolower(post('email')), (string)($_POST['password']??''), 'student', !empty($_POST['remember']));
  if($r['ok']) redirect($r['redirect']);
  $err=$r['error'];
}
