<script>const pw=document.getElementById('password');document.getElementById('showPw').onclick=()=>{pw.type=pw.type==='password'?'text':'password'};document.getElementById('loginForm').addEventListener('submit',()=>{document.getElementById('spin').classList.remove('d-none');document.getElementById('loginBtn').disabled=true});const scene=document.getElementById('scene'),card=document.getElementById('studentCard');scene.addEventListener('pointermove',e=>{if(matchMedia('(max-width:991px)').matches)return;const r=scene.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;card.style.transform=`perspective(700px) rotateY(${x*8}deg) rotateX(${-y*5}deg)`});scene.addEventListener('pointerleave',()=>card.style.transform='');</script></body></html>
